from datetime import datetime

from django.contrib.admin.views.main import PAGE_VAR
from django.contrib.auth.models import Group
from django.template import Library
from django.utils.html import format_html
from django.utils.safestring import mark_safe

register = Library()


@register.filter(name='strptime')
def strptime(value, mash):
    return datetime.strptime(value, mash)


@register.filter(name='has_group')
def has_group(user, group_name):
    group = Group.objects.get(name=group_name)
    return True if group in user.groups.all() else False


@register.inclusion_tag('admin/date_hierarchy.html', takes_context=True)
def power_date_hierarchy(context, cl):
    """
    Displays the date hierarchy for date drill-down functionality.
    """
    if cl.date_hierarchy:
        request = context.get('request')
        field_name = cl.date_hierarchy
        field = cl.opts.get_field(field_name)
        value__lte = request.GET.get(cl.date_hierarchy__lte)
        value__gte = request.GET.get(cl.date_hierarchy__gte)

        if value__lte:
            value__lte = datetime.strptime(value__lte, "%Y-%m-%d")

        if value__gte:
            value__gte = datetime.strptime(value__gte, "%Y-%m-%d")

        return {
            'field_name__lte': cl.date_hierarchy__lte,
            'field_name__gte': cl.date_hierarchy__gte,
            'field': field,
            'value__lte': value__lte,
            'value__gte': value__gte,
            'request': request,
        }


@register.simple_tag
def power_pagination(cl, i):
    if getattr(cl, 'multi_search_query', False):
        tag = '?'
        for k, v in cl.params.items():
            tag += '%s=%s&' % (k, v)

        for k, v in cl.multi_search_query.items():
            tag += '%s=%s&' % (k, v)

        if i == cl.paginator.ELLIPSIS:
            return format_html('{} ', cl.paginator.ELLIPSIS)
        elif i == cl.page_num:
            return format_html('<span class="this-page">{}</span> ', i)
        else:
            return format_html('<a href="{}p={}"{}>{}</a> ',
                               tag,
                               i,
                               mark_safe(' class="end"' if i == cl.paginator.num_pages else ''),
                               i)
    else:
        """
           Generates an individual page index link in a paginated list.
           """
        if i == cl.paginator.ELLIPSIS:
            return format_html('{} ', cl.paginator.ELLIPSIS)
        elif i == cl.page_num:
            return format_html('<span class="this-page">{}</span> ', i)
        else:
            return format_html('<a href="{}"{}>{}</a> ',
                               cl.get_query_string({PAGE_VAR: i}),
                               mark_safe(' class="end"' if i == cl.paginator.num_pages else ''),
                               i)
